insert into public.profils (id, data) values ('ia-030', $j${"domaine":"ia","categorie":"Communication, web et création","nom":"Webmaster, chargé(e) de contenus web","besoin":"Produire plus vite des contenus bien référencés, visibles sur Google et dans les réponses des IA.","reponses":{"M1":"Prendre en main ChatGPT, Claude, Mistral ou Gemini, les comparer et rédiger des prompts efficaces, sans exposer de données sensibles."},"parcours":[{"formation":"ia-webmaster","pourquoi":"Le plus adapté : référencement et contenus du site.","reponses":{"M2":"Stratégie éditoriale et GEO-SEO : des pages et articles optimisés pour Google et pour les réponses des IA.","M3":"Visuels et voix off pour habiller pages, articles et vidéos du site."}},{"formation":"ia-graphiste","pourquoi":"S'il produit aussi les visuels du site.","reponses":{"M2":"Prompts avancés, assistants et automatisations pour accélérer la production de contenus.","M3":"Bannières et illustrations créées avec Midjourney ou Ideogram, finalisées dans Photoshop."}}],"complements":[{"formation":"web-wordpress","pourquoi":"Gérer et faire évoluer le site WordPress ; certification Tosa."}],"motsCles":"webmaster, rédacteur web, chargé de contenus, SEO, GEO, référencement naturel, articles, blog, site internet, ChatGPT","categories":["Communication, web et création"],"ordre":26}$j$::jsonb) on conflict (id) do nothing;
insert into public.profils (id, data) values ('ia-031', $j${"domaine":"ia","categorie":"Communication, web et création","nom":"Graphiste, chargé(e) de communication visuelle","besoin":"Explorer plus de pistes créatives et livrer plus vite, en gardant la main sur le rendu final.","reponses":{"M1":"Prendre en main ChatGPT, Claude, Mistral ou Gemini, les comparer et rédiger des prompts efficaces, sans exposer de données sensibles."},"parcours":[{"formation":"ia-graphiste","pourquoi":"Le plus adapté : textes et visuels avec les outils IA du design.","reponses":{"M2":"Prompts avancés pour briefs, textes d'accompagnement et déclinaisons de campagnes.","M3":"Générer des pistes visuelles avec Midjourney ou Ideogram et les finaliser dans Photoshop."}}],"complements":[{"formation":"paoia-adobe","pourquoi":"L'IA intégrée à Photoshop et Illustrator, sans changer d'outil."}],"motsCles":"graphiste, infographiste, directeur artistique, maquettiste, Midjourney, Ideogram, Photoshop, création visuelle, pistes créatives","categories":["Communication, web et création"],"ordre":27}$j$::jsonb) on conflict (id) do nothing;
insert into public.profils (id, data) values ('ia-032', $j${"domaine":"ia","categorie":"Communication, web et création","nom":"Chargé(e) de communication ou de marketing","besoin":"Produire plus de contenus de campagne, textes et visuels, sans perdre en qualité ni en cohérence.","reponses":{"M1":"Prendre en main ChatGPT, Claude, Mistral ou Gemini, les comparer et rédiger des prompts efficaces, sans exposer de données sensibles."},"parcours":[{"formation":"ia-graphiste","pourquoi":"Le plus adapté : visuels et contenus de campagne.","reponses":{"M2":"Campagnes, emailings et posts : prompts avancés et assistants pour produire plus vite, avec contrôle.","M3":"Visuels de campagne et de réseaux sociaux créés avec l'IA, dans le respect de la charte."}},{"formation":"ia-webmaster","pourquoi":"Si le site et le référencement font partie de ses missions.","reponses":{"M2":"Articles et pages optimisés pour le référencement naturel et la visibilité dans les IA.","M3":"Visuels et voix off pour enrichir les contenus du site et des réseaux."}}],"complements":[{"formation":"video-ia-avatar","pourquoi":"Des vidéos avec avatar IA, déclinables en plusieurs langues."}],"motsCles":"chargé de communication, chargé de marketing, community manager, campagnes, emailing, newsletter, réseaux sociaux, contenus, IA générative","categories":["Communication, web et création"],"ordre":28}$j$::jsonb) on conflict (id) do nothing;
insert into public.profils (id, data) values ('pao-006', $j${"domaine":"pao","categorie":"Communication et marketing","nom":"Maquettiste ou assistant(e) PAO (imprimerie, édition, agence)","besoin":"Monter des documents prêts pour l'impression : catalogues, magazines, plaquettes.","reponses":{},"parcours":[{"formation":"pao-indesign","pourquoi":"Le plus adapté : la mise en page professionnelle.","reponses":{"Formation":"Gabarits, styles, longs documents et export PDF pour l'imprimeur ; certification Tosa."}},{"formation":"pao-illustrator","pourquoi":"Pour les logos, pictos et illustrations vectorielles.","reponses":{"Formation":"Logos, pictogrammes et illustrations nets à toutes les tailles ; certification Tosa."}},{"formation":"pao-photoshop-perf","pourquoi":"S'il maîtrise déjà les bases de Photoshop.","reponses":{"Formation":"Détourages, photomontages et retouches avancées pour l'impression."}}],"complements":[{"formation":"paoia-adobe","pourquoi":"Gagner du temps grâce à l'IA intégrée aux logiciels Adobe."}],"motsCles":"maquettiste, metteur en page, opérateur PAO, imprimerie, édition, catalogue, magazine, InDesign, impression, PDF","categories":["Communication et marketing"],"ordre":6}$j$::jsonb) on conflict (id) do nothing;
insert into public.profils (id, data) values ('bur-004', $j${"domaine":"bur","categorie":"Logistique et achats","nom":"Gestionnaire de stock, acheteur(se), logisticien(ne)","besoin":"Croiser des extractions (ERP, fournisseurs) et suivre stocks et achats sans ressaisie.","reponses":{},"parcours":[{"formation":"bur-excel-power","pourquoi":"Le plus adapté : importer, nettoyer et croiser des données.","reponses":{"Formation":"Power Query pour consolider les extractions, tableaux croisés et tableaux de bord de suivi des stocks et achats."}},{"formation":"bur-vba","pourquoi":"Pour automatiser des traitements répétitifs.","reponses":{"Formation":"Macros pour automatiser mises en forme, calculs et exports récurrents ; certification Tosa."}}],"complements":[],"motsCles":"gestionnaire de stock, magasinier, acheteur, approvisionneur, logisticien, supply chain, ERP, inventaire, extractions, Power Query","categories":["Logistique et achats"],"ordre":4}$j$::jsonb) on conflict (id) do nothing;
