-- 4. Compléments sans « pourquoi » : texte ajouté seulement s'il est vide
update public.profils set data = jsonb_set(data, '{complements}', (select jsonb_agg(case when e->>'formation' = 'paoia-design' and coalesce(e->>'pourquoi','') = '' then e || jsonb_build_object('pourquoi', 'Créer des visuels avec les outils IA du design (Midjourney, Ideogram).') else e end order by o) from jsonb_array_elements(data->'complements') with ordinality as t(e, o))), updated_at = now()
  where id = 'cao-002' and data->'complements' @> '[{"formation":"paoia-design","pourquoi":""}]'::jsonb;
